using System.Collections.Generic; using Cysharp.Threading.Tasks; using UnityEngine.AddressableAssets; using UnityEngine.ResourceManagement.AsyncOperations;
namespace Demo.Inventory { public sealed class InventoryDatabase { readonly Dictionary<int,ItemDefinition> definitions=new(); AsyncOperationHandle<IList<ItemDefinition>> handle; public async UniTask InitializeAsync(){handle=Addressables.LoadAssetsAsync<ItemDefinition>("ItemDefinition",x=>{if(x!=null)definitions[x.itemId]=x;}); await handle.Task;} public bool TryGet(int id,out ItemDefinition item)=>definitions.TryGetValue(id,out item); public void Release(){if(handle.IsValid())Addressables.Release(handle);definitions.Clear();} } }
